/* chassis_mpc_qpsol:(h[906x906,906nz],g[906],a[2516x906,5323nz],lba[2516],uba[2516],lbx[906],ubx[906],x0[906],lam_x0[906],lam_a0[2516],q[0x906],p[])->(x[906],cost,lam_a[2516],lam_x[906]) */
static int casadi_f2(const casadi_real** arg, casadi_real** res, casadi_int* iw, casadi_real* w, int mem) {
  OSQPSolver *work=casadi_f2_mem[mem];
  casadi_int i, n, offset;
  /* Set objective */
  if (arg[1]) {
    casadi_copy(arg[1], 906, w);
  } else {
    casadi_clear(w, 906);
  }
  if (osqp_update_data_vec(work, w, 0, 0)) return 1;
  /* Set bounds */
  if (arg[5]) {
    casadi_copy(arg[5], 906, w);
  } else {
    casadi_fill(w, 906, -casadi_inf);
  }
  if (arg[3]) {
    casadi_copy(arg[3], 2516, w+906);
  } else {
    casadi_fill(w+906, 2516, -casadi_inf);
  }
  if (arg[6]) {
    casadi_copy(arg[6], 906, w+3422);
  } else {
    casadi_fill(w+3422, 906, casadi_inf);
  }
  if (arg[4]) {
    casadi_copy(arg[4], 2516, w+4328);
  } else {
    casadi_fill(w+4328, 2516, casadi_inf);
  }
  /* Convert C++ infinity values to OSQP infinity */
  casadi_clip_min(w, 6844, -OSQP_INFTY, 0);
  casadi_clip_max(w, 6844, OSQP_INFTY, 0);
  if (osqp_update_data_vec(work, 0, w, w+3422)) return 1;
  /* Project Hessian */
  casadi_tri_project(arg[0], casadi_s0, w, 0);/* Get constraint matrix */
  offset = 0;
  for (i=0; i< 906; ++i) {
    w[906+offset] = 1;
    offset++;
    n = casadi_s1[i+1]-casadi_s1[i];
    casadi_copy(arg[2]+casadi_s1[i], n, w+offset+906);
    offset+= n;
  }
  /* Pass Hessian and constraint matrices */
  if (osqp_update_data_mat(work, w, 0, 906, w+906, 0, 6229)) return 1;
  osqp_cold_start(work);
  osqp_update_rho(work, 1.0000000000000001e-01);
  if (osqp_warm_start(work, arg[7], OSQP_NULL)) return 1;
  if (arg[8]) {
    casadi_copy(arg[8], 906, w);
  } else {
    casadi_clear(w, 906);
  }
  if (arg[9]) {
    casadi_copy(arg[9], 2516, w+906);
  } else {
    casadi_clear(w+906, 2516);
  }
  if (osqp_warm_start(work, OSQP_NULL, w)) return 1;
  if (osqp_solve(work)) return 1;
  if (res[1]) casadi_copy(&work->info->obj_val, 1, res[1]);
  if (res[0]) casadi_copy(work->solution->x, 906, res[0]);
  if (res[3]) casadi_copy(work->solution->y, 906, res[3]);
  if (res[2]) casadi_copy(work->solution->y+906, 2516, res[2]);
  if (work->info->status_val != OSQP_SOLVED) {
    if (work->info->status_val == OSQP_PRIMAL_INFEASIBLE || work->info->status_val == OSQP_MAX_ITER_REACHED || work->info->status_val == OSQP_DUAL_INFEASIBLE || work->info->status_val == OSQP_PRIMAL_INFEASIBLE_INACCURATE || work->info->status_val == OSQP_DUAL_INFEASIBLE_INACCURATE || work->info->status_val == OSQP_NON_CVX) {
      return 4;
    } else {
      return 1;
    }
  }
  return 0;
  return 0;
}

int casadi_f2_alloc_mem(void) {
  return casadi_f2_mem_counter++;
}

int casadi_f2_init_mem(int mem) {
  OSQPCscMatrix A, H;
  OSQPInt A_colind[907], A_row[6229], H_colind[907], H_row[906], i;
  OSQPSettings settings;
  casadi_real dummy[6229];
  casadi_clear(dummy, 6229);
  for (i=0;i<6229;++i) A_row[i] = casadi_s2[i];
  for (i=0;i<907;++i) A_colind[i] = casadi_s3[i];
  for (i=0;i<906;++i) H_row[i] = casadi_s4[i];
  for (i=0;i<907;++i) H_colind[i] = casadi_s5[i];
  A.m = 3422;
  A.n = 906;
  A.nz = 6229;
  A.nzmax = 6229;
  A.x = dummy;
  A.i = A_row;
  A.p = A_colind;
  H.m = 906;
  H.n = 906;
  H.nz = 906;
  H.nzmax = 906;
  H.x = dummy;
  H.i = H_row;
  H.p = H_colind;
  struct
  {
      OSQPInt n;
      OSQPInt m;
      OSQPCscMatrix * P;
      OSQPCscMatrix * A;
      OSQPFloat * q;
      OSQPFloat * l;
      OSQPFloat * u;
  } data;
  data.n = 906;
  data.m = 3422;
  data.P = &H;
  data.q = dummy;
  data.A = &A;
  data.l = dummy;
  data.u = dummy;
  osqp_set_default_settings(&settings);
  settings.rho = 1.0000000000000001e-01;
  settings.sigma = 9.9999999999999995e-07;
  settings.scaling = 10;
  settings.adaptive_rho = 1;
  settings.adaptive_rho_interval = 50;
  settings.adaptive_rho_tolerance = 5.;
  settings.max_iter = 4000;
  settings.eps_abs = 1.0000000000000000e-03;
  settings.eps_rel = 1.0000000000000000e-03;
  settings.eps_prim_inf = 1.0000000000000000e-04;
  settings.eps_dual_inf = 1.0000000000000000e-04;
  settings.alpha = 1.6000000000000001e+00;
  settings.delta = 9.9999999999999995e-07;
  settings.polishing = 0;
  settings.polish_refine_iter = 3;
  settings.verbose = 0;
  settings.scaled_termination = 0;
  settings.check_termination = 25;
  settings.warm_starting = 0;
  return osqp_setup(&casadi_f2_mem[mem], data.P, data.q, data.A, data.l, data.u, data.m, data.n, &settings)!=0;
}

void casadi_f2_free_mem(int mem) {
  osqp_cleanup(casadi_f2_mem[mem]);
}

int casadi_f2_checkout(void) {
  int mid;
  if (casadi_f2_unused_stack_counter>=0) {
    return casadi_f2_unused_stack[casadi_f2_unused_stack_counter--];
  } else {
    if (casadi_f2_mem_counter==CASADI_MAX_NUM_THREADS) {
      return -1;
    }
    mid = casadi_f2_alloc_mem();
    if (mid<0) {
      return -1;
    }
    if (casadi_f2_init_mem(mid)) {
      return -1;
    }
    return mid;
  }
}

void casadi_f2_release(int mem) {
  casadi_f2_unused_stack[++casadi_f2_unused_stack_counter] = mem;
  return;
}

void casadi_f2_incref(void) {
  casadi_f2_ref_counter++;
}

void casadi_f2_decref(void) {
  casadi_f2_ref_counter--;
  if (casadi_f2_ref_counter==0) {
    while (casadi_f2_mem_counter>0) {
      casadi_f2_free_mem(--casadi_f2_mem_counter);
    }
  }
}

